import socket, time, os
sock_path = "/tmp/vm.sock"
inbox = "/tmp/inbox"
log = "/tmp/console.log"
s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
for _ in range(100):
    try:
        s.connect(sock_path)
        break
    except Exception:
        time.sleep(0.2)
s.settimeout(0.5)
open(log, "w").write("=== console started ===\n")
last = 0
try:
    if os.path.exists(inbox):
        last = os.path.getsize(inbox)
except Exception:
    last = 0
while True:
    try:
        size = os.path.getsize(inbox)
        if size > last:
            with open(inbox, "rb") as f:
                f.seek(last)
                data = f.read()
            last = size
            for line in data.decode(errors="replace").splitlines():
                s.sendall(line.encode() + b"\n")
                with open(log, "a") as lf:
                    lf.write(">>> " + line + "\n")
    except Exception:
        pass
    try:
        while True:
            d = s.recv(4096)
            if not d:
                raise Exception("closed")
            with open(log, "a") as lf:
                lf.write(d.decode(errors="replace"))
    except socket.timeout:
        continue
    except Exception:
        with open(log, "a") as lf:
            lf.write("=== console closed ===\n")
        break
PYEOF

